<?php
defined('ABSPATH') || exit;
function prime_contact_action($kind,$label,$class='') {
    $s=prime_business();$href='';
    if($kind==='phone' && $s['phone'])$href='tel:'.(str_starts_with(preg_replace('/\D/','',$s['phone']),'0')?'+61'.substr(preg_replace('/\D/','',$s['phone']),1):preg_replace('/[^+\d]/','',$s['phone']));
    if($kind==='email' && $s['email'])$href='mailto:'.$s['email'];
    if($kind==='whatsapp' && class_exists('PCE_Approved'))$href=PCE_Approved::whatsapp();
    return $href?'<a class="'.esc_attr($class).'" href="'.esc_url($href).'">'.esc_html($label).'</a>':'<span class="'.esc_attr($class).' pp-unavailable" aria-disabled="true" title="Contact details awaiting client approval">'.esc_html($label).'<small>Details pending</small></span>';
}
function prime_logo() { return '<a class="pp-brand" href="'.esc_url(home_url('/')).'">'.prime_home_icon('home').'<span>Prime Domestic<small>&amp; Cleaning Services</small></span></a>'; }
function prime_approved_header() { ?>
<header class="pp-header"><div class="pp-container pp-header-inner"><?php echo prime_logo();?><button class="pp-menu-toggle" aria-expanded="false" aria-controls="pp-navigation">Menu <span aria-hidden="true">☰</span></button><nav id="pp-navigation" aria-label="Main navigation"><a href="<?php echo esc_url(home_url('/'));?>">Home</a><details class="pp-services-menu"><summary>Services</summary><div><?php foreach(['lease','regular','carpet'] as $k)echo '<a href="'.esc_url(prime_page_link($k)).'">'.esc_html(prime_pages_map()[$k][0]).'</a>';?></div></details><?php foreach(array_merge(['prices'=>'Prices','about'=>'About','contact'=>'Contact'],prime_has_posts()?['blog'=>'Blog']:[]) as $k=>$label)echo '<a href="'.esc_url(prime_page_link($k)).'"'.(prime_page_key()===$k?' aria-current="page"':'').'>'.$label.'</a>';?></nav><div class="pp-header-actions"><?php echo prime_contact_action('phone','0491 245 156');?><a class="pp-button" href="<?php echo esc_url(prime_page_link('prices'));?>">Get my estimate</a></div></div></header>
<?php }
function prime_approved_footer(){ $s=prime_business(); ?>
<footer class="pp-footer"><div class="pp-container"><div class="pp-footer-grid"><div><?php echo prime_logo();?><p><?php echo esc_html("A small, family-run cleaning team from Malvern East, looking after homes across Melbourne's south-east.");?></p></div><div><h2>Our services</h2><?php foreach(['lease','regular','carpet'] as $key)echo '<a href="'.esc_url(prime_page_link($key)).'">'.esc_html(prime_pages_map()[$key][0]).'</a>';?></div><div><h2>Company</h2><?php foreach(array_merge(['prices','about','contact'],prime_has_posts()?['blog']:[],['privacy','terms']) as $key)if(($page=prime_page_object($key)) && $page->post_status==='publish')echo '<a href="'.esc_url(prime_page_link($key)).'">'.esc_html(prime_pages_map()[$key][0]).'</a>';if($s['reviews_url'])echo '<a href="'.esc_url($s['reviews_url']).'">Google reviews</a>';?></div><div><h2>Get in touch</h2><?php echo prime_contact_action('phone',$s['phone']).prime_contact_action('whatsapp','WhatsApp').prime_contact_action('email',$s['email']);?><hr><p>ABN <?php echo esc_html($s['abn']?:'[pending approval]');?><br>Payment is due on completion by bank transfer or PayID.<br>No GST charged.</p></div></div><div class="pp-copyright"><span>© <?php echo esc_html(wp_date('Y'));?> Prime Domestic and Cleaning Services · ABN 16 938 734 164</span><span>Melbourne, Australia</span></div></div></footer><nav class="pp-mobile-actions" aria-label="Quick contact actions"><?php echo prime_contact_action('phone','Call').prime_contact_action('whatsapp','WhatsApp');?><a href="<?php echo esc_url(prime_page_link('prices'));?>">Estimate</a></nav><?php if($s['whatsapp'])echo '<div class="pp-floating-wa" title="Got a question? Message us — we’re friendlier than a chatbot.">'.prime_contact_action('whatsapp','WhatsApp').'</div>'; }
add_action('init',function(){
add_shortcode('prime_starting_price',function($atts){
    $service=sanitize_key($atts['service']??'regular');$values=[];$settings=prime_business();
    foreach($settings['grids'][$service]??[] as $value)if(PCE_Approved::money($value)!==null)$values[]=(float)$value;
    $minimum=class_exists('PCE_Approved')?PCE_Approved::money($settings['minimum']??null):null;
    return '<p class="pp-starting">'.($values && $minimum!==null?'From AUD '.esc_html(number_format(max(min($values),$minimum),2)):'Starting price awaiting approval').'</p>';
});
add_shortcode('prime_discount_message',function(){return '<p class="pp-callout">'.esc_html(prime_business()['discount_message']??'Recurring-discount wording awaiting approval.').'</p>';});
add_shortcode('prime_carpet_rates',function(){$s=prime_business();$out='<div class="pp-rate-grid">';foreach(['bedroom'=>'Bedroom','living'=>'Lounge / living','hallway'=>'Hallway','stairs'=>'Flight of stairs'] as $key=>$name)$out.='<div class="pp-card">'.prime_home_icon($key==='stairs'?'home':'brush').'<h3>'.esc_html($name).'</h3><p class="pp-starting">'.(isset($s['carpets'][$key])?'AUD '.esc_html(number_format($s['carpets'][$key],2)):'Rate pending').'</p><p>Per '.esc_html(strtolower($name)).'</p></div>';return $out.'</div>';});
add_shortcode('prime_contact_details',function(){$s=prime_business();return '<div class="pp-contact-links">'.prime_contact_action('phone',$s['phone']?:'Call us').prime_contact_action('whatsapp','WhatsApp us').prime_contact_action('email',$s['email']?:'Email us').'</div>';});
add_shortcode('prime_response_notice',function(){return '<p class="pp-callout">'.esc_html(prime_business()['response_notice']).'</p>';});
add_shortcode('prime_abn',function(){return '<p>ABN '.esc_html(prime_business()['abn']?:'[pending approval]').'</p>';});
add_shortcode('prime_reviews_link',function(){$u=prime_business()['reviews_url'];return $u?'<a href="'.esc_url($u).'">Read our Google reviews →</a>':'';});
add_shortcode('prime_service_areas',function(){$s=prime_business();$out='<div class="pp-area-layout"><div class="pp-map-placeholder" role="img" aria-label="Static service-area map placeholder, awaiting approved suburb boundaries"><div class="pp-map-ring"><div><strong>Melbourne</strong><span>Map placeholder</span></div></div><p>Static map awaiting approved suburb boundaries.<br>Diagram is not to scale.</p></div><div>';foreach([1=>'0–15 km',2=>'15–25 km'] as $zone=>$label){$names=[];foreach($s['suburbs']??[] as $r)if((int)$r['zone']===$zone)$names[]=$r['name'].' '.$r['postcode'];$out.='<section class="pp-card"><h3>Zone '.$zone.' · '.$label.'</h3><p>'.($zone===1?'No travel fee for approved suburbs.':(isset($s['travel_fee'])?'AUD '.esc_html($s['travel_fee']).' travel per visit.':'Travel fee pending.')).'</p><p>'.esc_html($names?implode(', ',$names):'Approved suburb list pending.').'</p></section>';}$out.='<p><a class="pp-button" href="'.esc_url(add_query_arg('prime_service','regular',prime_page_link('prices'))).'">Unlisted suburb? Request a custom quote</a></p></div></div>';return $out;});
add_shortcode('prime_blog_listing','prime_blog_listing');
});
function prime_blog_card($post,$featured=false){$id=$post->ID;$categories=get_the_category($id);ob_start();?><article class="pp-blog-card <?php echo $featured?'pp-featured':'';?>"><a class="pp-post-image" href="<?php echo esc_url(get_permalink($id));?>"><?php if(has_post_thumbnail($id))echo get_the_post_thumbnail($id,$featured?'large':'medium_large',['loading'=>'lazy']);else echo '<span class="pp-photo-placeholder">Article photograph pending</span>';?></a><div><p class="pp-eyebrow"><?php echo esc_html($categories?$categories[0]->name:'Journal');?></p><h2><a href="<?php echo esc_url(get_permalink($id));?>"><?php echo esc_html(get_the_title($id));?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt($post),24));?></p><p class="pp-small"><?php echo esc_html(get_the_date('j F Y',$id));?></p><a href="<?php echo esc_url(get_permalink($id));?>">Read article →</a></div></article><?php return ob_get_clean();}
function prime_blog_listing(){ $page=max(1,(int)get_query_var('paged'),(int)get_query_var('page'),absint($_GET['journal_page']??1));$category=absint($_GET['journal_category']??(is_category()?get_queried_object_id():0));$q=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>7,'paged'=>$page,'cat'=>$category]);$out='<nav class="pp-category-pills" aria-label="Article categories"><a href="'.esc_url(prime_page_link('blog')).'">All articles</a>';foreach(get_categories(['hide_empty'=>true]) as $cat)$out.='<a href="'.esc_url(add_query_arg('journal_category',$cat->term_id,prime_page_link('blog'))).'">'.esc_html($cat->name).'</a>';$out.='</nav>';if(!$q->have_posts())return $out.'<div class="pp-empty"><span class="pp-empty-icon" aria-hidden="true">▤</span><h2>Our first tips are on the way.</h2><p>In the meantime, the oven isn’t going to clean itself.</p><a class="pp-button" href="'.esc_url(prime_page_link('prices')).'">Get my estimate</a></div>';
    foreach($q->posts as $i=>$post){if($i===1)$out.='<div class="pp-blog-grid">';$out.=prime_blog_card($post,$i===0);}
    if(count($q->posts)>1)$out.='</div>';if($q->max_num_pages>1){$out.='<nav class="pp-pagination" aria-label="Article pagination">';for($i=1;$i<=$q->max_num_pages;$i++)$out.='<a '.($i===$page?'aria-current="page" ':'').'href="'.esc_url(add_query_arg(['journal_page'=>$i,'journal_category'=>$category],prime_page_link('blog'))).'">'.$i.'</a>';$out.='</nav>';}wp_reset_postdata();return $out;
}
add_filter('render_block_core/image',function($html,$block){if(!str_contains($block['attrs']['className']??'','prime-service-photo'))return $html;return preg_replace_callback('/src="([^"]+)-1280.webp"/',function($m)use($block){return 'src="'.$m[1].'-1280.webp" srcset="'.$m[1].'-640.webp 640w, '.$m[1].'-1280.webp 1280w" sizes="(max-width: 767px) 100vw, 50vw" width="1280" height="853" loading="'.(str_contains($block['attrs']['className'],'pp-hero-photo')?'eager" fetchpriority="high':'lazy').'" decoding="async"';},$html);},10,2);

function prime_article_body($content) {
    $links=[];$index=0;
    $body=preg_replace_callback('/<h([23])([^>]*)>(.*?)<\/h\1>/is',function($m)use(&$links,&$index){$index++;if(preg_match('/\bid=["\']([^"\']+)["\']/',$m[2],$existing))$id=$existing[1];else $id='article-section-'.$index;$links[]='<a href="#'.esc_attr($id).'">'.esc_html(wp_strip_all_tags($m[3])).'</a>';return '<h'.$m[1].$m[2].(isset($existing[1])?'':' id="'.esc_attr($id).'"').'>'.$m[3].'</h'.$m[1].'>';},$content);
    return ($links?'<nav class="pp-article-toc" aria-label="On this page"><h2>On this page</h2>'.implode('',$links).'</nav>':'').'<div class="pp-article-content">'.$body.'</div>';
}
function prime_related_posts($id) {
    $q=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>[$id],'ignore_sticky_posts'=>true]);if(!$q->have_posts())return '';$html='<section class="pp-related"><h2>More from the journal</h2><div class="pp-blog-grid">';foreach($q->posts as $post)$html.=prime_blog_card($post);wp_reset_postdata();return $html.'</div></section>';
}

